import { createHmac } from "node:crypto";
import { describe, expect, it } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const secret = "test-secret";
const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (header: object, payload: object, key = secret) => {
  const body = `${b64(header)}.${b64(payload)}`;
  return `${body}.${createHmac("sha256", key).update(body).digest("base64url")}`;
};
const future = () => Math.floor(Date.now() / 1000) + 3600;

describe("verifyToken", () => {
  it("accepts a valid unexpired token and returns its claims", () => {
    const exp = future();
    expect(verifyToken(sign({ alg: "HS256" }, { sub: "u1", exp }), secret)).toEqual({ sub: "u1", exp });
  });

  it("rejects expired tokens so stolen old tokens stop working", () => {
    const token = sign({ alg: "HS256" }, { sub: "u1", exp: 1 });
    expect(() => verifyToken(token, secret)).toThrow("expired");
  });

  it("rejects tokens signed with a different secret", () => {
    const token = sign({ alg: "HS256" }, { sub: "u1", exp: future() }, "attacker");
    expect(() => verifyToken(token, secret)).toThrow("signature");
  });

  it("rejects tampered payloads so users cannot impersonate others", () => {
    const [h, , s] = sign({ alg: "HS256" }, { sub: "u1", exp: future() }).split(".");
    const forged = `${h}.${b64({ sub: "admin", exp: future() })}.${s}`;
    expect(() => verifyToken(forged, secret)).toThrow("signature");
  });

  it("rejects alg:none tokens to block signature bypass", () => {
    const token = `${b64({ alg: "none" })}.${b64({ sub: "admin", exp: future() })}.`;
    expect(() => verifyToken(token, secret)).toThrow("alg");
  });

  it("rejects tokens with no exp so tokens cannot live forever", () => {
    const token = sign({ alg: "HS256" }, { sub: "u1" });
    expect(() => verifyToken(token, secret)).toThrow("claims");
  });
});

